   212→    // 重新勾选时若列为空则恢复全选，避免"表勾选但 0 字段"被服务端视为全字段放开
   213→    if (willEnable && (scopeCols[table.id]?.size ?? 0) === 0) {
   214→      setScopeCols((prev) => ({ ...prev, [table.id]: new Set(table.columns.map((c) => c.name)) }));
   215→    }
   216→  };
